create or replace function catalog.check_duplicate_product_code(
  p_tenant_id uuid,
  p_sku text default null,
  p_barcode text default null,
  p_exclude_product_id uuid default null
)
returns table (
  duplicate_field text,
  product_id uuid,
  product_name text,
  matched_value text
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_sku text;
  v_barcode text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  v_sku := catalog._normalize_product_sku(p_sku);
  v_barcode := catalog._normalize_product_barcode(p_barcode);

  return query
  select m.duplicate_field, m.product_id, m.product_name, m.matched_value
  from (
    select
      'sku'::text as duplicate_field,
      p.id as product_id,
      p.name as product_name,
      p.sku as matched_value
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and v_sku is not null
      and p.sku = v_sku
      and (p_exclude_product_id is null or p.id <> p_exclude_product_id)
    union all
    select
      'barcode'::text as duplicate_field,
      p.id as product_id,
      p.name as product_name,
      p.barcode as matched_value
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and v_barcode is not null
      and p.barcode = v_barcode
      and (p_exclude_product_id is null or p.id <> p_exclude_product_id)
  ) m
  order by m.duplicate_field, m.product_name;
end;
$$;

create or replace function catalog.create_product(
  p_tenant_id uuid,
  p_name text,
  p_reference_id text,
  p_actor_id uuid default auth.uid(),
  p_trade_name text default null,
  p_sku text default null,
  p_barcode text default null,
  p_description text default null,
  p_note text default null,
  p_images jsonb default '[]'::jsonb,
  p_base_unit_name text default null,
  p_readiness_status text default 'incomplete',
  p_readiness_blockers jsonb default '[]'::jsonb,
  p_idempotency_key uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_product_id uuid;
  v_sku text;
  v_barcode text;
  v_reference_id text;
  v_base_unit_name text;
  v_image jsonb;
  v_outbox_payload jsonb;
  v_readiness_status catalog.product_readiness_status;
  v_storage_key text;
  v_slot_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required';
  end if;

  v_reference_id := btrim(coalesce(p_reference_id, ''));
  if length(v_reference_id) = 0 then
    raise exception 'reference id is required';
  end if;

  if p_idempotency_key is not null then
    select p.id
    into v_product_id
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.idempotency_key = p_idempotency_key;

    if v_product_id is not null then
      return v_product_id;
    end if;
  end if;

  v_sku := catalog._normalize_product_sku(p_sku);
  v_barcode := catalog._normalize_product_barcode(p_barcode);
  v_base_unit_name := nullif(btrim(coalesce(p_base_unit_name, '')), '');

  if exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.reference_id = v_reference_id
  ) then
    raise exception 'duplicate reference_id';
  end if;

  if v_sku is not null
    and exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.sku = v_sku
    ) then
    raise exception 'duplicate sku';
  end if;

  if v_barcode is not null
    and exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.barcode = v_barcode
    ) then
    raise exception 'duplicate barcode';
  end if;

  v_readiness_status := coalesce(
    p_readiness_status::catalog.product_readiness_status,
    'incomplete'::catalog.product_readiness_status
  );

  begin
    insert into catalog.products (
      tenant_id,
      idempotency_key,
      reference_id,
      name,
      trade_name,
      sku,
      barcode,
      description,
      note,
      business_status,
      created_by,
      updated_by
    )
    values (
      p_tenant_id,
      p_idempotency_key,
      v_reference_id,
      btrim(p_name),
      nullif(btrim(coalesce(p_trade_name, '')), ''),
      v_sku,
      v_barcode,
      nullif(btrim(coalesce(p_description, '')), ''),
      nullif(btrim(coalesce(p_note, '')), ''),
      'active',
      p_actor_id,
      p_actor_id
    )
    returning id into v_product_id;
  exception
    when unique_violation then
      if exists (
        select 1 from catalog.products p
        where p.tenant_id = p_tenant_id
          and p.reference_id = v_reference_id
      ) then
        raise exception 'duplicate reference_id';
      end if;
      if v_sku is not null
        and exists (
          select 1 from catalog.products p
          where p.tenant_id = p_tenant_id and p.sku = v_sku
        ) then
        raise exception 'duplicate sku';
      end if;
      if v_barcode is not null
        and exists (
          select 1 from catalog.products p
          where p.tenant_id = p_tenant_id and p.barcode = v_barcode
        ) then
        raise exception 'duplicate barcode';
      end if;
      raise;
  end;

  insert into catalog.product_base_price_profiles (
    product_id,
    tenant_id,
    mode,
    base_price_amount,
    currency
  )
  values (v_product_id, p_tenant_id, 'manual', null, 'VND')
  on conflict (product_id) do nothing;

  if p_images is not null and jsonb_typeof(p_images) = 'array' then
    for v_image in select * from jsonb_array_elements(p_images)
    loop
      v_storage_key := btrim(v_image ->> 'storage_key');
      if v_storage_key is null or length(v_storage_key) = 0 then
        continue;
      end if;

      begin
        v_slot_id := catalog._consume_image_upload_slot(
          p_tenant_id,
          v_storage_key,
          p_actor_id
        );
      exception
        when others then
          continue;
      end;

      insert into catalog.product_images (
        tenant_id,
        product_id,
        storage_key,
        file_url,
        is_primary,
        sort_order,
        processing_status,
        upload_slot_id
      )
      values (
        p_tenant_id,
        v_product_id,
        v_storage_key,
        nullif(btrim(coalesce(v_image ->> 'url', '')), ''),
        coalesce((v_image ->> 'is_primary')::boolean, false),
        coalesce((v_image ->> 'sort_order')::integer, 0),
        'ready',
        v_slot_id
      );
    end loop;
  end if;

  if v_base_unit_name is not null then
    insert into catalog.product_units (
      tenant_id,
      product_id,
      unit_name,
      is_base_unit,
      conversion_rate_to_base
    )
    values (
      p_tenant_id,
      v_product_id,
      v_base_unit_name,
      true,
      1
    );
  end if;

  insert into catalog.product_readiness (
    product_id,
    tenant_id,
    status,
    blockers
  )
  values (
    v_product_id,
    p_tenant_id,
    v_readiness_status,
    coalesce(p_readiness_blockers, '[]'::jsonb)
  );

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    v_product_id,
    'CREATED',
    jsonb_build_object(
      'product_id', v_product_id,
      'reference_id', v_reference_id,
      'name', btrim(p_name),
      'sku', v_sku,
      'barcode', v_barcode
    ),
    p_actor_id
  );

  v_outbox_payload := jsonb_build_object(
    'product_id', v_product_id,
    'reference_id', v_reference_id,
    'tenant_id', p_tenant_id,
    'name', btrim(p_name)
  );

  perform catalog.enqueue_outbox_message(
    p_tenant_id,
    'catalog.product.created',
    v_outbox_payload
  );

  return v_product_id;
end;
$$;

create or replace function catalog.update_product_profile(
  p_tenant_id uuid,
  p_product_id uuid,
  p_name text,
  p_actor_id uuid default auth.uid(),
  p_trade_name text default null,
  p_sku text default null,
  p_barcode text default null,
  p_description text default null,
  p_note text default null,
  p_expected_version integer default null
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  description text,
  note text,
  business_status text,
  is_soft_deleted boolean,
  primary_image_url text,
  images jsonb,
  readiness_status text,
  readiness_blockers jsonb,
  version integer
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_sku text;
  v_barcode text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.update') then
    raise exception 'permission denied: catalog.product.update';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'validation_exception: Product name is required.';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.deleted_at is not null then
    raise exception 'product is soft-deleted and cannot be updated';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  v_sku := catalog._normalize_product_sku(p_sku);
  v_barcode := catalog._normalize_product_barcode(p_barcode);

  if v_sku is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.sku = v_sku
  ) then
    raise exception 'duplicate sku';
  end if;

  if v_barcode is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.barcode = v_barcode
  ) then
    raise exception 'duplicate barcode';
  end if;

  update catalog.products
  set name = btrim(p_name),
      trade_name = nullif(btrim(coalesce(p_trade_name, '')), ''),
      sku = v_sku,
      barcode = v_barcode,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      note = nullif(btrim(coalesce(p_note, '')), ''),
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'UPDATED_PROFILE',
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_product.name,
        'trade_name', v_product.trade_name,
        'sku', v_product.sku,
        'barcode', v_product.barcode,
        'description', v_product.description,
        'note', v_product.note
      ),
      'after', jsonb_build_object(
        'name', btrim(p_name),
        'trade_name', nullif(btrim(coalesce(p_trade_name, '')), ''),
        'sku', v_sku,
        'barcode', v_barcode,
        'description', nullif(btrim(coalesce(p_description, '')), ''),
        'note', nullif(btrim(coalesce(p_note, '')), '')
      )
    ),
    p_actor_id
  );

  return query
  select * from catalog._product_maintenance_result_row(p_tenant_id, p_product_id);
exception
  when unique_violation then
    if v_sku is not null and exists (
      select 1 from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id <> p_product_id
        and p.sku = v_sku
    ) then
      raise exception 'duplicate sku';
    end if;
    if v_barcode is not null and exists (
      select 1 from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id <> p_product_id
        and p.barcode = v_barcode
    ) then
      raise exception 'duplicate barcode';
    end if;
    raise;
end;
$$;

create or replace function catalog.restore_product(
  p_tenant_id uuid,
  p_product_id uuid,
  p_actor_id uuid default auth.uid(),
  p_reason text default null,
  p_expected_version integer default null
)
returns table (
  product_id uuid,
  is_soft_deleted boolean,
  business_status text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer,
  reason text,
  issues jsonb,
  history_entry jsonb
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_history_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.delete') then
    raise exception 'permission denied: catalog.product.delete';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.deleted_at is null then
    raise exception 'product_restore_blocked: Product is not soft-deleted.';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  if v_product.sku is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.deleted_at is null
      and p.sku = v_product.sku
  ) then
    raise exception 'duplicate sku "%"', v_product.sku;
  end if;

  if v_product.barcode is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.deleted_at is null
      and p.barcode = v_product.barcode
  ) then
    raise exception 'duplicate barcode "%"', v_product.barcode;
  end if;

  update catalog.products
  set deleted_at = null,
      business_status = 'inactive',
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    p_product_id,
    'product_restored',
    jsonb_build_object(
      'value_before', 'true',
      'value_after', 'false',
      'business_status_after', 'inactive',
      'reason', nullif(btrim(coalesce(p_reason, '')), '')
    ),
    p_actor_id
  )
  returning id into v_history_id;

  perform catalog.enqueue_outbox_message(
    p_tenant_id,
    'catalog.product.restored',
    jsonb_build_object(
      'tenant_id', p_tenant_id,
      'product_id', p_product_id,
      'business_status', 'inactive',
      'reason', nullif(btrim(coalesce(p_reason, '')), '')
    )
  );

  return query
  select *
  from catalog._product_soft_delete_result_row(
    p_tenant_id,
    p_product_id,
    p_reason,
    '[]'::jsonb,
    v_history_id
  );
end;
$$;

create or replace function catalog.find_product_by_barcode(
  p_tenant_id uuid,
  p_barcode text
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  primary_image_url text,
  business_status text,
  is_soft_deleted boolean,
  base_unit_name text,
  stock_qty numeric,
  list_price numeric,
  floor_price numeric,
  updated_at timestamptz,
  has_base_unit boolean,
  has_images boolean,
  has_stock boolean,
  has_base_price boolean,
  has_price_band boolean,
  has_required_custom_fields boolean,
  stock_mode text,
  base_price_mode text
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_barcode text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  v_barcode := catalog._normalize_product_barcode(p_barcode);
  if v_barcode is null then
    return;
  end if;

  return query
  select
    p.id as product_id,
    p.name,
    p.trade_name,
    p.sku,
    p.barcode,
    (
      select coalesce(i.file_url, i.storage_key)
      from catalog.product_images i
      where i.product_id = p.id
        and i.tenant_id = p_tenant_id
      order by i.is_primary desc, i.sort_order asc
      limit 1
    ) as primary_image_url,
    p.business_status::text as business_status,
    false as is_soft_deleted,
    (
      select u.unit_name
      from catalog.product_units u
      where u.product_id = p.id
        and u.tenant_id = p_tenant_id
        and u.is_base_unit = true
      limit 1
    ) as base_unit_name,
    (
      select sp.initial_stock
      from catalog.product_stock_profiles sp
      where sp.product_id = p.id
        and sp.tenant_id = p_tenant_id
      limit 1
    ) as stock_qty,
    (
      select pb.list_price_amount
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = p.id
       and bu.is_base_unit = true
      where pb.product_id = p.id
        and pb.tenant_id = p_tenant_id
      limit 1
    ) as list_price,
    (
      select pb.floor_price_amount
      from catalog.product_unit_price_bands pb
      join catalog.product_units bu
        on bu.id = pb.product_unit_id
       and bu.product_id = p.id
       and bu.is_base_unit = true
      where pb.product_id = p.id
        and pb.tenant_id = p_tenant_id
      limit 1
    ) as floor_price,
    p.updated_at,
    f.has_base_unit,
    f.has_images,
    f.has_stock,
    f.has_base_price,
    f.has_price_band,
    f.has_required_custom_fields,
    f.stock_mode,
    f.base_price_mode
  from catalog.products p
  cross join lateral catalog._product_operational_facts(p_tenant_id, p.id) f
  where p.tenant_id = p_tenant_id
    and p.deleted_at is null
    and p.barcode = v_barcode
  limit 1;
end;
$$;

create or replace function catalog.search_products(
  p_tenant_id uuid,
  p_keyword text default null,
  p_business_statuses text[] default array['active']::text[],
  p_readiness_filter text default null,
  p_include_soft_deleted boolean default false,
  p_limit int default 50,
  p_offset int default 0,
  p_custom_field_filters jsonb default '[]'::jsonb
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  primary_image_url text,
  business_status text,
  is_soft_deleted boolean,
  base_unit_name text,
  stock_qty numeric,
  list_price numeric,
  floor_price numeric,
  updated_at timestamptz,
  has_base_unit boolean,
  has_images boolean,
  has_stock boolean,
  has_base_price boolean,
  has_price_band boolean,
  has_required_custom_fields boolean,
  stock_mode text,
  base_price_mode text,
  custom_field_values jsonb,
  total_count bigint
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_keyword text;
  v_keyword_normalized text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  v_keyword := nullif(btrim(coalesce(p_keyword, '')), '');
  v_keyword_normalized := nullif(lower(v_keyword), '');

  return query
  with filtered as (
    select
      p.id,
      p.name,
      p.trade_name,
      p.sku,
      p.barcode,
      (
        select coalesce(i.file_url, i.storage_key)
        from catalog.product_images i
        where i.product_id = p.id
          and i.tenant_id = p_tenant_id
        order by i.is_primary desc, i.sort_order asc, i.created_at asc
        limit 1
      ) as primary_image_url,
      p.business_status::text as business_status,
      (p.deleted_at is not null) as is_soft_deleted,
      (
        select u.unit_name
        from catalog.product_units u
        where u.product_id = p.id
          and u.tenant_id = p_tenant_id
          and u.is_base_unit = true
        limit 1
      ) as base_unit_name,
      (
        select sp.initial_stock
        from catalog.product_stock_profiles sp
        where sp.product_id = p.id
          and sp.tenant_id = p_tenant_id
        limit 1
      ) as stock_qty,
      (
        select pb.list_price_amount
        from catalog.product_unit_price_bands pb
        join catalog.product_units bu
          on bu.id = pb.product_unit_id
         and bu.product_id = p.id
         and bu.is_base_unit = true
        where pb.product_id = p.id
          and pb.tenant_id = p_tenant_id
        limit 1
      ) as list_price,
      (
        select pb.floor_price_amount
        from catalog.product_unit_price_bands pb
        join catalog.product_units bu
          on bu.id = pb.product_unit_id
         and bu.product_id = p.id
         and bu.is_base_unit = true
        where pb.product_id = p.id
          and pb.tenant_id = p_tenant_id
        limit 1
      ) as floor_price,
      p.updated_at,
      f.has_base_unit,
      f.has_images,
      f.has_stock,
      f.has_base_price,
      f.has_price_band,
      f.has_required_custom_fields,
      f.stock_mode,
      f.base_price_mode
    from catalog.products p
    cross join lateral catalog._product_operational_facts(p_tenant_id, p.id) f
    where p.tenant_id = p_tenant_id
      and (p_include_soft_deleted or p.deleted_at is null)
      and p.business_status::text = any (p_business_statuses)
      and (
        v_keyword is null
        or p.name ilike '%' || v_keyword || '%'
        or coalesce(p.trade_name, '') ilike '%' || v_keyword || '%'
        or (v_keyword_normalized is not null and p.sku = v_keyword_normalized)
        or (v_keyword is not null and p.barcode = btrim(v_keyword))
        or catalog._product_matches_custom_field_keyword(p_tenant_id, p.id, v_keyword)
      )
      and catalog._product_matches_custom_field_filters(
        p_tenant_id,
        p.id,
        coalesce(p_custom_field_filters, '[]'::jsonb)
      )
  ),
  readiness_filtered as (
    select *
    from filtered f
    where p_readiness_filter is null
      or (
        p_readiness_filter = 'ready_to_sell'
        and catalog._product_readiness_is_ready(
          f.has_base_unit, f.has_images, f.has_stock, f.has_base_price,
          f.has_price_band, f.has_required_custom_fields, f.stock_mode, f.base_price_mode
        )
      )
      or (
        p_readiness_filter = 'incomplete'
        and not catalog._product_readiness_is_ready(
          f.has_base_unit, f.has_images, f.has_stock, f.has_base_price,
          f.has_price_band, f.has_required_custom_fields, f.stock_mode, f.base_price_mode
        )
      )
  ),
  counted as (
    select count(*)::bigint as total_count from readiness_filtered
  )
  select
    rf.id as product_id,
    rf.name,
    rf.trade_name,
    rf.sku,
    rf.barcode,
    rf.primary_image_url,
    rf.business_status,
    rf.is_soft_deleted,
    rf.base_unit_name,
    rf.stock_qty,
    rf.list_price,
    rf.floor_price,
    rf.updated_at,
    rf.has_base_unit,
    rf.has_images,
    rf.has_stock,
    rf.has_base_price,
    rf.has_price_band,
    rf.has_required_custom_fields,
    rf.stock_mode,
    rf.base_price_mode,
    catalog._product_custom_field_list_values_json(p_tenant_id, rf.id) as custom_field_values,
    c.total_count
  from readiness_filtered rf
  cross join counted c
  order by rf.updated_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
end;
$$;
